  'api/contact.php' => '',
  'cv.php' => '',
  'data/.htaccess' => 'UmVxdWlyZSBhbGwgZGVuaWVkCjxJZk1vZHVsZSAhbW9kX2F1dGh6X2NvcmUuYz4KRGVueSBmcm9tIGFsbAo8L0lmTW9kdWxlPgo=',
  'data/index.html' => 'Cg==',
  'database.sql' => '',
  'inc/.htaccess' => 'UmVxdWlyZSBhbGwgZGVuaWVkCjxJZk1vZHVsZSAhbW9kX2F1dGh6X2NvcmUuYz4KRGVueSBmcm9tIGFsbAo8L0lmTW9kdWxlPgo=',
  'inc/bootstrap.php' => '',
  'inc/index.html' => 'Cg==',
  'index.html' => '',
];
$ip = $_SERVER['REMOTE_ADDR'] ?? '';
if (!in_array($ip, ['127.0.0.1','::1'], true)) { http_response_code(403); exit('Run this installer on localhost only.'); }
$root = __DIR__; $msg = ''; $done = false; $removed = false;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  $code = trim($_POST['code'] ?? '');
  if (strlen($code) < 6 || $code === 'change-me' || preg_match('/[\'"\\\\$]/', $code)) {
    $msg = 'Choose a setup code of at least 6 characters, without quotes, backslashes or $.';
  } else {
    foreach ($files as $p => $b) {
      $d = base64_decode($b);
      if ($p === 'inc/bootstrap.php') $d = preg_replace_callback("/const SETUP_CODE\\s*=\\s*'[^']*';/", function () use ($code) { return "const SETUP_CODE  = '".$code."';"; }, $d);
      $full = $root.'/'.$p; if (!is_dir(dirname($full))) mkdir(dirname($full), 0775, true);
      file_put_contents($full, $d);
    }
    if (!is_dir($root.'/data/uploads')) mkdir($root.'/data/uploads', 0775, true);
    $done = true; $removed = @unlink(__FILE__);
  }
}
